<script>
const EXT = {
  NAME: "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
  DESIGNATION: "http://ihris.org/fhir/StructureDefinition/designation",
  DEPARTMENT: "http://ihris.org/fhir/StructureDefinition/department",
  FACILITY: "http://ihris.org/fhir/StructureDefinition/facility",
  GRADE: "http://ihris.org/fhir/StructureDefinition/salary-grade",
  STATUS: "http://ihris.org/fhir/StructureDefinition/position-status",
  CODE: "http://ihris.org/fhir/StructureDefinition/position-code",
  MAX: "http://ihris.org/fhir/StructureDefinition/maximum-practitioners",
  DESCRIPTION: "http://ihris.org/fhir/StructureDefinition/description",
  MIN_REQ: "http://ihris.org/fhir/StructureDefinition/minimum-requirements",
  ADD_REQ: "http://ihris.org/fhir/StructureDefinition/additional-requirements",
  COMMENTS: "http://ihris.org/fhir/StructureDefinition/comments",
  SPEC: "http://ihris.org/fhir/StructureDefinition/position-specification",
};

const DES_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/ls-designation-profile";

export default {
  name: "ViewPosition",
  props: ["queries"],
  components: {
    "position-specification": () =>
      import("../shared/PositionSpecification.vue"),
  },

  data() {
    return {
      loading: false,
      error: null,
      position: {},
      positionResource: null,
    };
  },

  mounted() {
    if (this.queries && this.queries.id) {
      this.loadPosition(this.queries.id);
    } else {
      this.error = "No position ID provided.";
    }
  },

  methods: {
    extValue(resource, url, key) {
      const ext = (resource.extension || []).find((e) => e.url === url);
      return ext ? ext[key] : null;
    },

    subExtValue(ext, url, key) {
      const sub = (ext.extension || []).find((e) => e.url === url);
      return sub ? sub[key] : null;
    },

    statusKey(code) {
      if (!code) return "default";
      const c = code.toLowerCase();
      if (c.includes("active") || c === "open") return "active";
      if (
        c.includes("inactive") ||
        c.includes("closed") ||
        c.includes("frozen")
      )
        return "closed";
      if (c.includes("draft") || c.includes("pending")) return "pending";
      return "default";
    },

    async loadPosition(id) {
      this.loading = true;
      this.error = null;
      try {
        const params = new URLSearchParams({
          _id: id,
          _include: "Basic:posdesignation",
        });
        params.append("_include", "Basic:facility");
        params.append("_include", "Basic:salarygrade");

        const res = await fetch(`/fhir/Basic?${params}`);
        if (!res.ok) throw new Error("Server error: " + res.status);
        const bundle = await res.json();

        const entries = bundle.entry || [];
        const posEntry = entries.find(
          (e) =>
            e.resource &&
            e.resource.id === id &&
            e.resource.resourceType === "Basic",
        );
        if (!posEntry) throw new Error("Position not found.");
        const r = posEntry.resource;
        this.positionResource = r;

        // Build lookups from included resources
        const desById = {};
        const gradeById = {};
        let facilityName = null;

        for (const e of entries) {
          const inc = e.resource;
          if (!inc || inc.id === id) continue;
          if (inc.resourceType === "Location") {
            facilityName = inc.name || null;
          } else if (inc.resourceType === "Basic") {
            const profiles = (inc.meta && inc.meta.profile) || [];
            if (profiles.includes(DES_PROFILE)) {
              desById[inc.id] =
                this.extValue(inc, EXT.NAME, "valueString") || inc.id;
            } else {
              gradeById[inc.id] =
                this.extValue(inc, EXT.NAME, "valueString") || inc.id;
            }
          }
        }

        const desRef = this.extValue(r, EXT.DESIGNATION, "valueReference");
        const desId =
          desRef && desRef.reference ? desRef.reference.split("/")[1] : null;

        const facRef = this.extValue(r, EXT.FACILITY, "valueReference");

        const gradeRef = this.extValue(r, EXT.GRADE, "valueReference");
        const gradeId =
          gradeRef && gradeRef.reference
            ? gradeRef.reference.split("/")[1]
            : null;

        const statusCoding = this.extValue(r, EXT.STATUS, "valueCoding");

        // Parse specifications — collect qualification name refs for batch resolution
        const qualNameRefs = new Set();
        const rawSpecs = (r.extension || [])
          .filter((e) => e.url === EXT.SPEC)
          .map((specExt) => {
            const groupOpCoding = (specExt.extension || []).find(
              (e) => e.url === "spec-group-operator",
            );
            const groupOpC = groupOpCoding ? groupOpCoding.valueCoding : null;

            const qualificationCriteria = (specExt.extension || [])
              .filter(
                (e) =>
                  e.url ===
                  "http://ihris.org/fhir/StructureDefinition/spec-qualification-criterion",
              )
              .map((critExt) => {
                const opCoding = this.subExtValue(
                  critExt,
                  "spec-criterion-operator",
                  "valueCoding",
                );
                const lvCoding = this.subExtValue(
                  critExt,
                  "qualification-level",
                  "valueCoding",
                );
                const nameRef = this.subExtValue(
                  critExt,
                  "qualification-name",
                  "valueReference",
                );
                if (nameRef && nameRef.reference)
                  qualNameRefs.add(nameRef.reference);
                return {
                  criterionOperator: opCoding
                    ? opCoding.display || opCoding.code
                    : null,
                  qualificationLevel: lvCoding
                    ? lvCoding.display || lvCoding.code
                    : null,
                  _qualNameRef: nameRef ? nameRef.reference : null,
                  qualificationName: nameRef ? nameRef.display || null : null,
                };
              });

            const experienceCriteria = (specExt.extension || [])
              .filter(
                (e) =>
                  e.url ===
                  "http://ihris.org/fhir/StructureDefinition/spec-experience-criterion",
              )
              .map((critExt) => {
                const opCoding = this.subExtValue(
                  critExt,
                  "spec-criterion-operator",
                  "valueCoding",
                );
                return {
                  criterionOperator: opCoding
                    ? opCoding.display || opCoding.code
                    : null,
                  minimumYears: this.subExtValue(
                    critExt,
                    "minimum-years",
                    "valuePositiveInt",
                  ),
                  jobTitle: this.subExtValue(
                    critExt,
                    "job-title",
                    "valueString",
                  ),
                };
              });

            const otherRequirements = (specExt.extension || [])
              .filter((e) => e.url === "other-requirement")
              .map((e) => e.valueString)
              .filter(Boolean);

            return {
              groupOperator: groupOpC
                ? groupOpC.display || groupOpC.code
                : null,
              qualificationCriteria,
              experienceCriteria,
              otherRequirements,
            };
          });

        // Batch-fetch qualification name resources if any refs collected
        const qualNameById = {};
        if (qualNameRefs.size > 0) {
          const ids = [...qualNameRefs]
            .map((ref) => ref.split("/")[1])
            .filter(Boolean);
          if (ids.length > 0) {
            try {
              const qnRes = await fetch(
                `/fhir/Basic?_id=${ids.join(",")}&_count=${ids.length}`,
              );
              if (qnRes.ok) {
                const qnBundle = await qnRes.json();
                for (const e of qnBundle.entry || []) {
                  if (e.resource && e.resource.resourceType === "Basic") {
                    qualNameById[e.resource.id] =
                      this.extValue(e.resource, EXT.NAME, "valueString") ||
                      null;
                  }
                }
              }
            } catch (_) {
              /* non-critical */
            }
          }
        }

        // Resolve qualification names now that we have the lookup
        const specifications = rawSpecs.map((spec) => ({
          ...spec,
          qualificationCriteria: spec.qualificationCriteria.map((qc) => {
            const refId = qc._qualNameRef
              ? qc._qualNameRef.split("/")[1]
              : null;
            return {
              criterionOperator: qc.criterionOperator,
              qualificationLevel: qc.qualificationLevel,
              qualificationName:
                (refId && qualNameById[refId]) ||
                qc.qualificationName ||
                qc._qualNameRef ||
                null,
            };
          }),
        }));

        this.position = {
          id: r.id,
          title: this.extValue(r, EXT.NAME, "valueString") || "",
          designation: desId
            ? desById[desId] || desRef.display || desId
            : (desRef && desRef.display) || "",
          department: (() => {
            const c = this.extValue(r, EXT.DEPARTMENT, "valueCoding");
            return c ? c.display || c.code : "";
          })(),
          facility: facilityName || (facRef && facRef.display) || "",
          grade: gradeId
            ? gradeById[gradeId] || gradeRef.display || gradeId
            : (gradeRef && gradeRef.display) || "",
          code: this.extValue(r, EXT.CODE, "valueString") || "",
          maxPractitioners: this.extValue(r, EXT.MAX, "valueInteger"),
          activePractitioners: null,
          status: statusCoding ? statusCoding.display || statusCoding.code : "",
          statusCode: statusCoding ? statusCoding.code : "",
          description: this.extValue(r, EXT.DESCRIPTION, "valueString") || "",
          minimumRequirements:
            this.extValue(r, EXT.MIN_REQ, "valueString") || "",
          additionalRequirements:
            this.extValue(r, EXT.ADD_REQ, "valueString") || "",
          comments: this.extValue(r, EXT.COMMENTS, "valueString") || "",
          specifications,
        };

        // Fetch active occupant count (non-blocking)
        this.loadActivePractitioners(id);
      } catch (err) {
        console.error("loadPosition error", err);
        this.error = err.message || "Failed to load position.";
      } finally {
        this.loading = false;
      }
    },

    async loadActivePractitioners(positionId) {
      try {
        const res = await fetch(
          `/fhir/PractitionerRole?_summary=count&roleposition=Basic/${positionId}&active=true`,
        );
        if (res.ok) {
          const data = await res.json();
          this.$set(this.position, "activePractitioners", data.total || 0);
        }
      } catch (_) {
        /* non-critical */
      }
    },

    scrollTo(section) {
      const el = document.getElementById("section-" + section);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },

    editPosition() {
      this.$router.push({
        path: "/custom/create-position",
        query: { path: "/lesotho/components/position", id: this.position.id },
      });
    },

    goBack() {
      this.$router.push({
        path: "/custom/index",
        query: { path: "/lesotho/components/position" },
      });
    },
  },
};
</script>

